<script setup>
import { ref,reactive,computed,onMounted } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { notify } from '../../services/notifications.js';
import { money } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
const route=useRoute(),router=useRouter(),editing=computed(()=>!!route.params.id),loading=ref(true),saving=ref(false),error=ref(''),features=ref('');
const form=reactive({name:'',icon:'store',previousPrice:0,price:0,durationDays:30,features:[],maxStores:1,maxProducts:100,active:true,featured:false,sortOrder:0});
onMounted(async()=>{try{if(editing.value){Object.assign(form,await api.get(`/admin/plans/${route.params.id}`));features.value=form.features.join('\n')}}catch(e){error.value=e.message}finally{loading.value=false}});
async function save(){saving.value=true;error.value='';try{form.features=features.value.split('\n').map(s=>s.trim()).filter(Boolean);if(editing.value)await api.put(`/admin/plans/${route.params.id}`,form);else await api.post('/admin/plans',form);notify.success('Plan guardado.');router.push('/app/settings?tab=planes')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
</script>
<template><div><RouterLink to="/app/settings?tab=planes" class="p-back-link"><Icon name="back" :size="14"/>Volver a planes</RouterLink><header class="p-page-header"><div><h1>{{editing?'Editar plan':'Creá un plan para crecer'}}</h1><p>Definí sus beneficios, precio y capacidad. Se mostrará en la página de inicio.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><form v-else class="p-form" @submit.prevent="save"><div class="p-two-column"><div><section class="p-section-card"><div class="p-section-title"><h2>Identidad y precio</h2></div><div class="p-form-grid"><div class="p-field"><label for="plan-name">Nombre *</label><input id="plan-name" v-model="form.name" required maxlength="80"/></div><div class="p-field"><label for="plan-icon">Ícono</label><select id="plan-icon" v-model="form.icon"><option v-for="i in ['store','sparkles','crown','package','chart','star','shield','globe']" :key="i" :value="i">{{i}}</option></select></div><div class="p-field"><label for="plan-price">Precio actual (ARS) *</label><input id="plan-price" v-model.number="form.price" type="number" min="0" step="0.01" required/></div><div class="p-field"><label for="plan-previous">Precio anterior (ARS)</label><input id="plan-previous" v-model.number="form.previousPrice" type="number" min="0" step="0.01"/><small>0 para no mostrar un precio tachado.</small></div><div class="p-field"><label for="plan-duration">Duración del plan (días) *</label><input id="plan-duration" v-model.number="form.durationDays" type="number" min="1" max="3650" step="1" required/></div><div class="p-field"><label for="plan-order">Orden en la página</label><input id="plan-order" v-model.number="form.sortOrder" type="number" min="0" step="1"/></div></div></section><section class="p-section-card"><div class="p-section-title"><h2>Capacidad y beneficios</h2></div><div class="p-form-grid"><div class="p-field"><label for="plan-stores">Cantidad de tiendas *</label><input id="plan-stores" v-model.number="form.maxStores" type="number" min="1" max="1000" step="1" required/></div><div class="p-field"><label for="plan-products">Productos por tienda *</label><input id="plan-products" v-model.number="form.maxProducts" type="number" min="0" step="1" required/><small>0 significa productos ilimitados.</small></div><div class="p-field full"><label for="plan-features">Funcionalidades incluidas</label><textarea id="plan-features" v-model="features" rows="7" placeholder="Una funcionalidad por línea"/><small>Se muestra una lista de beneficios en la home y en Mi suscripción.</small></div><label class="p-check"><input v-model="form.active" type="checkbox"/>Plan disponible</label><label class="p-check"><input v-model="form.featured" type="checkbox"/>Destacar como recomendado</label></div></section></div><aside class="p-order-summary"><span class="p-badge green" v-if="form.featured">Recomendado</span><div style="margin:18px 0;color:#00897b"><Icon :name="form.icon" :size="35"/></div><h3>{{form.name||'Nombre del plan'}}</h3><del v-if="form.previousPrice>form.price" class="p-muted">{{money(form.previousPrice)}}</del><div style="font-size:28px;font-weight:700;color:#215043">{{money(form.price)}}</div><p class="p-help">cada {{form.durationDays}} días</p><hr class="p-separator"/><ul class="p-mini-list"><li v-for="(feature,i) in features.split('\n').filter(Boolean)" :key="i"><Icon name="check" :size="14"/>{{feature}}</li></ul></aside></div><footer class="p-form-footer"><small>Vista previa del plan actualizada al editar.</small><div class="p-form-actions"><RouterLink to="/app/settings?tab=planes" class="btn btn-secondary">Cancelar</RouterLink><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando...':'Guardar plan'}}</button></div></footer></form></div></template>
